@@ -0,0 +1,14 @@
+import { ledger } from '../ledger.js';
+
+export async function chargeCrypto(walletAddress: string, amountUsd: number) {
+  const quote = await fetch(`https://api.commerce.coinbase.com/quote?usd=${amountUsd}`).then((r) => r.json());
+  const charge = await fetch('https://api.commerce.coinbase.com/charges', {
+    method: 'POST',
+    headers: { 'X-CC-Api-Key': process.env.COINBASE_KEY! },
+    body: JSON.stringify({ wallet: walletAddress, amount: quote.btc }),
+  }).then((r) => r.json());
+  await ledger.record({ kind: 'charge', provider: 'coinbase', ref: charge.id, amountUsd });
+  return charge.id;
+}

